'use strict';
const $=id=>document.getElementById(id), state={files:[],active:0,type:'text',logo:null,busy:false};
const controls=['text','color','mode','size','opacity','angle','gap','position','shadow','format'];
function status(message){$('status').textContent=message;}
function settings(){return Object.fromEntries(controls.map(id=>[id,$(id).type==='checkbox'?$(id).checked:$(id).value]));}
function labels(){for(const id of ['size','opacity','angle','gap'])$(id+'-val').textContent=$(id).value+(id==='angle'?'°':'%');$('position').disabled=$('mode').value==='tile';$('gap').disabled=$('mode').value!=='tile';}
function render(image,canvas,opts,preview=false){const scale=preview?Math.min(1,1400/Math.max(image.width,image.height)):1;canvas.width=Math.round(image.width*scale);canvas.height=Math.round(image.height*scale);const ctx=canvas.getContext('2d');if(opts.format==='jpeg'){ctx.fillStyle='#fff';ctx.fillRect(0,0,canvas.width,canvas.height);}ctx.drawImage(image,0,0,canvas.width,canvas.height);const w=canvas.width,h=canvas.height,base=Math.min(w,h),size=base*Number(opts.size)/100;const logo=state.type==='logo'?state.logo:null;if(state.type==='logo'&&!logo)return;if(state.type==='text'&&!opts.text.trim())return;ctx.font=`600 ${size}px system-ui, sans-serif`;const lines=opts.text.split('\n'),lh=size*1.35;let mw=logo?size*4:Math.max(...lines.map(t=>ctx.measureText(t).width)),mh=logo?mw*logo.height/logo.width:lines.length*lh;const theta=Number(opts.angle)*Math.PI/180;const rw=Math.abs(mw*Math.cos(theta))+Math.abs(mh*Math.sin(theta)),rh=Math.abs(mw*Math.sin(theta))+Math.abs(mh*Math.cos(theta));function stamp(x,y){ctx.save();ctx.translate(x,y);ctx.rotate(theta);ctx.globalAlpha=Number(opts.opacity)/100;if(opts.shadow){ctx.shadowColor='#0009';ctx.shadowBlur=Math.max(1,size*.12);ctx.shadowOffsetY=size*.05;}if(logo)ctx.drawImage(logo,-mw/2,-mh/2,mw,mh);else{ctx.fillStyle=opts.color;ctx.textAlign='center';ctx.textBaseline='middle';lines.forEach((line,i)=>ctx.fillText(line,0,(i-(lines.length-1)/2)*lh));}ctx.restore();}
if(opts.mode==='tile'){const gap=base*Number(opts.gap)/100,dx=Math.max(10,rw+gap),dy=Math.max(10,rh+gap);let row=0;for(let y=-rh;y<h+rh;y+=dy,row++)for(let x=-rw+(row%2)*dx/2;x<w+rw;x+=dx)stamp(x,y);}else{const margin=base*.04,x=opts.position==='center'?w/2:opts.position.endsWith('r')?w-margin-rw/2:margin+rw/2,y=opts.position==='center'?h/2:opts.position.startsWith('b')?h-margin-rh/2:margin+rh/2;stamp(Math.max(rw/2,Math.min(w-rw/2,x)),Math.max(rh/2,Math.min(h-rh/2,y)));}}
function update(){for(const id of [...controls,'logo','files','choose','add','clear','reset','demo'])$(id).disabled=state.busy;document.querySelectorAll('[data-type],.thumb').forEach(b=>b.disabled=state.busy);labels();if(state.busy){$('position').disabled=true;$('gap').disabled=true;}const item=state.files[state.active];$('empty').hidden=!!item;$('preview').hidden=!item;$('dimensions').textContent=item?`${item.image.width} × ${item.image.height} · ${state.active+1}/${state.files.length}`:'等待添加图片';const valid=!!item&&(state.type==='text'?!!$('text').value.trim():!!state.logo);$('download').disabled=!valid||state.busy;$('batch').disabled=!valid||state.busy;if(item)render(item.image,$('preview'),settings(),true);}
function film(){const area=$('film');area.replaceChildren();state.files.forEach((item,i)=>{const b=document.createElement('button');b.className='thumb'+(i===state.active?' selected':'');b.title=item.name;b.setAttribute('aria-label','预览 '+item.name);const img=document.createElement('img');img.src=item.url;img.alt=item.name;b.append(img);b.onclick=()=>{state.active=i;film();update();};area.append(b);});}
function decode(file){return new Promise((resolve,reject)=>{const url=URL.createObjectURL(file),image=new Image();image.onload=()=>resolve({image,url,name:file.name});image.onerror=()=>{URL.revokeObjectURL(url);reject(new Error('无法读取图片'));};image.src=url;});}
async function addFiles(files){if(state.busy){status('正在导出，请稍后添加图片');return;}const errors=[];for(const file of files){if(!['image/png','image/jpeg','image/webp'].includes(file.type)){errors.push(file.name+'：仅支持 JPG、PNG、WebP');continue;}if(file.size>30*1024*1024){errors.push(file.name+'：超过 30 MB');continue;}try{const item=await decode(file);if(item.image.width*item.image.height>40000000){URL.revokeObjectURL(item.url);errors.push(file.name+'：像素过大');continue;}state.files.push(item);}catch{errors.push(file.name+'：读取失败');}}film();update();status(errors.length?errors.join('；'):`已添加 ${state.files.length} 张图片`);$('files').value='';}
$('choose').onclick=$('add').onclick=()=>$('files').click();$('files').onchange=e=>addFiles(e.target.files);const stage=$('stage');for(const event of ['dragenter','dragover'])stage.addEventListener(event,e=>{e.preventDefault();stage.classList.add('drag');});for(const event of ['dragleave','drop'])stage.addEventListener(event,e=>{e.preventDefault();stage.classList.remove('drag');});stage.addEventListener('drop',e=>addFiles(e.dataTransfer.files));
for(const id of controls)$(id).addEventListener('input',update);
document.querySelectorAll('[data-type]').forEach(b=>b.onclick=()=>{state.type=b.dataset.type;document.querySelectorAll('[data-type]').forEach(t=>t.classList.toggle('active',t===b));$('text-settings').hidden=state.type!=='text';$('logo-settings').hidden=state.type!=='logo';update();});
$('logo').onchange=async e=>{const file=e.target.files[0];if(!file)return;if(file.size>10*1024*1024){status('Logo 请小于 10 MB');return;}try{const item=await decode(file);if(item.image.width*item.image.height>40000000){URL.revokeObjectURL(item.url);throw Error();}state.logo=item.image;URL.revokeObjectURL(item.url);$('logo-name').textContent=file.name;update();}catch{status('Logo 无法读取，请换一张图片');}};
$('clear').onclick=()=>{state.files.forEach(i=>URL.revokeObjectURL(i.url));state.files=[];state.active=0;film();update();status('已清空图片');};
$('reset').onclick=()=>{const defaults={text:'© 我的原创作品',color:'#ffffff',mode:'single',size:6,opacity:55,angle:-25,gap:20,position:'br',format:'png'};for(const [k,v]of Object.entries(defaults))$(k).value=v;$('shadow').checked=true;update();};
function blobFor(item,opts){return new Promise((resolve,reject)=>{const canvas=document.createElement('canvas');try{render(item.image,canvas,opts);canvas.toBlob(blob=>{canvas.width=canvas.height=1;blob&&blob.type==='image/'+opts.format?resolve(blob):reject(Error('浏览器不支持此导出格式'));},'image/'+opts.format,.92);}catch(e){reject(e);}});}
function filename(item,opts,index){return `${String(index+1).padStart(3,'0')}-${item.name.replace(/\.[^.]+$/,'')}-watermark.${opts.format==='jpeg'?'jpg':opts.format}`;}
function save(blob,name){const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),30000);}
$('download').onclick=async()=>{state.busy=true;update();try{const opts=settings();save(await blobFor(state.files[state.active],opts),filename(state.files[state.active],opts,state.active));status('图片已生成，下载已开始');}catch{status('导出失败，可能图片过大，请换用更小的图片');}finally{state.busy=false;update();}};
// ZIP store method: no dependency, UTF-8 filenames, CRC32 integrity.
const crcTable=Array.from({length:256},(_,n)=>{for(let k=0;k<8;k++)n=n&1?0xedb88320^(n>>>1):n>>>1;return n>>>0;});
function crc32(bytes){let c=0xffffffff;for(const b of bytes)c=crcTable[(c^b)&255]^(c>>>8);return(c^0xffffffff)>>>0;}
async function zip(items){let offset=0;const local=[],central=[];for(const item of items){const bytes=new Uint8Array(await item.blob.arrayBuffer()),name=new TextEncoder().encode(item.name),crc=crc32(bytes),head=new Uint8Array(30+name.length),v=new DataView(head.buffer);v.setUint32(0,0x04034b50,true);v.setUint16(4,20,true);v.setUint16(6,0x800,true);v.setUint32(14,crc,true);v.setUint32(18,bytes.length,true);v.setUint32(22,bytes.length,true);v.setUint16(26,name.length,true);head.set(name,30);local.push(head,bytes);const c=new Uint8Array(46+name.length),d=new DataView(c.buffer);d.setUint32(0,0x02014b50,true);d.setUint16(4,20,true);d.setUint16(6,20,true);d.setUint16(8,0x800,true);d.setUint32(16,crc,true);d.setUint32(20,bytes.length,true);d.setUint32(24,bytes.length,true);d.setUint16(28,name.length,true);d.setUint32(42,offset,true);c.set(name,46);central.push(c);offset+=head.length+bytes.length;}const size=central.reduce((n,a)=>n+a.length,0),end=new Uint8Array(22),v=new DataView(end.buffer);v.setUint32(0,0x06054b50,true);v.setUint16(8,items.length,true);v.setUint16(10,items.length,true);v.setUint32(12,size,true);v.setUint32(16,offset,true);return new Blob([...local,...central,end],{type:'application/zip'});}
$('batch').onclick=async()=>{state.busy=true;update();try{const opts=settings(),items=[];for(let i=0;i<state.files.length;i++){status(`正在处理 ${i+1} / ${state.files.length}…`);items.push({name:filename(state.files[i],opts,i),blob:await blobFor(state.files[i],opts)});}save(await zip(items),'印记-水印图片.zip');status(`已打包 ${items.length} 张图片`);}catch{status('批量导出失败，请减少图片数量或尺寸后重试');}finally{state.busy=false;update();}};
$('demo').onclick=()=>{const c=document.createElement('canvas');c.width=1600;c.height=1200;const ctx=c.getContext('2d');const g=ctx.createLinearGradient(0,0,1600,1200);g.addColorStop(0,'#c8d7bb');g.addColorStop(1,'#4a7460');ctx.fillStyle=g;ctx.fillRect(0,0,1600,1200);ctx.fillStyle='#e5e9d6';ctx.beginPath();ctx.arc(1190,260,150,0,Math.PI*2);ctx.fill();for(let i=0;i<5;i++){ctx.fillStyle=['#8aa88b','#668c75','#416d59','#2a5747','#173c34'][i];ctx.beginPath();ctx.moveTo(0,650+i*110);for(let x=0;x<=1600;x+=20)ctx.lineTo(x,620+i*100+Math.sin(x/300+i)*140);ctx.lineTo(1600,1200);ctx.lineTo(0,1200);ctx.fill();}ctx.fillStyle='#fff';ctx.font='24px sans-serif';ctx.fillText('A QUIET MOMENT / 2026',90,100);c.toBlob(b=>addFiles([new File([b],'山间-示例.png',{type:'image/png'})]));};update();
